def bfs_shortest_path(graph, start, end):
    # Initialize visited set and queue
    visited = set()
    queue = deque([start])

    # Dictionary to keep track of the parent for each node
    parent = {start: None}

    while queue:
        current_node = queue.popleft()

        if current_node == end:
